def header(active=''):
 return '<a class="skip" href="#inhalt">Zum Inhalt</a><header><div class="wrap header-row">'+brand+'<button class="menu" aria-expanded="false" aria-controls="navigation">Menü <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="Hauptnavigation">'+''.join('<a '+('aria-current="page" ' if active==p else '')+'href="'+p+'">'+t+'</a>' for p,t in [('/#entdecken','Die App'),('/idee/','Die Idee'),('/ausblick/','Was kommt'),('/hilfe/','Hilfe')])+'<a class="button small" href="/ausprobieren/">OnPath ausprobieren '+icon('arrow')+'</a></nav></div></header>'
def footer():return '<footer><div class="wrap"><div class="footer-grid"><div>'+brand+'<p>Wandern und Radfahren.<br>Mit einem Plan, der zu dir passt.</p><span class="fine">Von Christian Neuhaus entwickelt. Der App-Code ist öffentlich.</span></div><div><b>OnPath</b><a href="/wandern/">Wandern</a><a href="/radfahren/">Radfahren</a><a href="/idee/">Die Idee dahinter</a><a href="/ausblick/">Was als Nächstes kommt</a></div><div><b>Gut zu wissen</b><a href="/hilfe/">Hilfe & erste Schritte</a><a href="/datenschutz/">Datenschutz</a><a href="/projekt/">Projekt & Bildnachweis</a></div><div><b>Mitmachen</b><a href="/ausprobieren/">Tester werden</a><a href="'+GITHUB+'/issues">Fehler melden ↗</a><a href="'+GITHUB+'">Quellcode auf GitHub ↗</a></div></div><div class="footer-bottom"><span>© 2026 OnPath · Christian Neuhaus</span><span>Android · Deutsch & Englisch · In Entwicklung</span></div></div></footer><button class="backtop" aria-label="Nach oben" hidden>↑</button>'
PAGES={}
def page(path,title,desc,body,active=''):
 PAGES[path]=(title,desc,body,active)
def ph(eyebrow,title,desc,breadcrumb=''):
 return '<section class="page-hero"><div class="wrap">'+('<div class="breadcrumb"><a href="/">Start</a> <span>/</span> '+breadcrumb+'</div>' if breadcrumb else '')+'<p class="eyebrow">'+eyebrow+'</p><h1>'+title+'</h1><p class="lead">'+desc+'</p></div></section>'
def button(url,text,outline=False):return '<a class="button'+(' outline' if outline else '')+'" href="'+url+'">'+text+icon('arrow')+'</a>'
def notice(title,text):return '<aside class="notice"><b>'+title+'</b><p>'+text+'</p></aside>'
def cta():return '<section class="section"><div class="wrap"><div class="cta"><p class="eyebrow">Gemeinsam besser machen</p><h2>Kommst du eine Runde mit?</h2><p>OnPath ist noch jung. Gesucht werden Menschen, die draußen unterwegs sind und sagen, was im Alltag klappt – und was noch nicht.</p><div class="actions">'+button('/ausprobieren/','Testversion kennenlernen')+'</div><span class="fine">Für Android ab Version 8 · Noch nicht im Google Play Store</span></div></div></section>'
DEMO={'de':dict(top='Eine Tour. Ein neuer Plan.',tag='So funktioniert’s',aria='Schematische Tour mit einem zusätzlichen Zwischenstopp',cafe='Pause am Café',start='Start',end='Ziel',ctl='Beispielablauf',b=['1. Planen','2. Ändern','3. Weiter'],t=['Du hast Start und Ziel gewählt. OnPath verbindet die Punkte über Wege.','Du möchtest zum Café? Ergänze den Ort als Zwischenstopp. OnPath passt den weiteren Weg an.','Weiter geht’s. Deine bisherige Tour bleibt aufgezeichnet, auch wenn du den Plan änderst.'],fine='Vereinfachte Darstellung, keine bedienbare App-Karte.'),'en':dict(top='One tour. A new plan.',tag='How it works',aria='Schematic tour with an added stop',cafe='Café stop',start='Start',end='Finish',ctl='Example steps',b=['1. Plan','2. Change','3. Go on'],t=['You chose a start and a destination. OnPath connects them along paths.','Fancy a café? Add it as a stop. OnPath adjusts the rest of the way.','On you go. Your recording keeps running, even though the plan changed.'],fine='Simplified illustration, not the app’s map.')}
def route_demo(lang='de'):
    D=DEMO[lang]
    buttons=''.join('<button data-demo="'+str(i)+'" data-text="'+D['t'][i]+'" aria-pressed="'+('true' if i==0 else 'false')+'">'+D['b'][i]+'</button>' for i in range(3))
    return '<div class="demo"><div class="demo-top"><span>'+D['top']+'</span><span class="tag">'+D['tag']+'</span></div><svg class="route-demo" viewBox="0 0 520 330" role="img" aria-label="'+D['aria']+'"><path class="terrain" d="M-40 220C90 80 100 330 280 100S500 40 570 160M-40 250C90 110 100 360 280 130S500 70 570 190M-40 280C90 140 100 390 280 160S500 100 570 220"/><path class="stream" d="M360-20C210 70 430 150 310 220S270 300 330 360"/><path class="way" d="M60 260 120 210 170 230 235 125 320 100 375 160 440 70M120 210 220 255 310 215 375 160"/><path id="old-route" d="M60 260 120 210 170 230 235 125 320 100 440 70"/><path id="demo-route" d="M60 260 120 210 170 230 235 125 320 100 440 70"/><circle class="start-point" cx="60" cy="260" r="9"/><circle class="end-point" cx="440" cy="70" r="9"/><g id="cafe-dot" opacity="0"><circle cx="310" cy="215" r="9"/><rect x="305" y="234" width="120" height="34" rx="5"/><text x="320" y="256">'+D['cafe']+'</text></g><text class="map-label" x="38" y="292">'+D['start']+'</text><text class="map-label" x="425" y="44">'+D['end']+'</text></svg><div class="demo-controls" aria-label="'+D['ctl']+'">'+buttons+'</div><p id="demo-text" aria-live="polite">'+D['t'][0]+'</p><span class="fine">'+D['fine']+'</span></div>'
MORE={'de':dict(eye='Auf dem Rad und zu Fuß',h='Du bist unterwegs, OnPath denkt mit.',lead='OnPath sagt dir, wann du ankommst, wo du abbiegst und was vor dir liegt – ohne dass du lange suchen musst.',items=[('route','Gute Routen für jede Tour.','Für jede Aktivität rechnet OnPath anders: mit dem Rad über Radwege und ruhige Nebenstraßen, mit dem Gravelbike gern auf Schotter, mit dem Mountainbike auf Trails, zu Fuß auf Wegen bis zu deiner Schwierigkeit. Hauptstraßen nur, wenn es nicht anders geht.'),('clock','Du weißt, wann du ankommst.','Nach etwa 15 Minuten richtet sich die Ankunftszeit nach deinem Tempo, getrennt für bergauf, flach und bergab.'),('pin','Hat die Hütte offen?','Ein Tipp auf den Ort öffnet ihn in Google Maps, mit Öffnungszeiten und Bildern. Zurück in OnPath nimmst du ihn als Stopp in die Route.'),('vibrate','Das Handy bleibt in der Tasche.','Vor einer Abzweigung vibriert es: einmal für links, zweimal für rechts. Der Sperrbildschirm zeigt die nächste Abzweigung und die Ankunftszeit.'),('profile','Keine bösen Überraschungen.','Vor dem Start siehst du Steigungen, Untergrund und Hinweise wie „120 m Schieben · 2 steile Abschnitte“ oder „Fähre – Fahrzeiten prüfen“.'),('cable','Mit Seilbahn oder Bus? Die Tour stimmt trotzdem.','Fahrten werden erkannt und lassen sich am Ende einfach herausnehmen.')],links=[('/radfahren/','Mehr zum Radfahren'),('/wandern/','Mehr zum Wandern')]),'en':dict(eye='On the bike and on foot',h='You are out there. OnPath thinks ahead.',lead='OnPath tells you when you will arrive, where to turn and what lies ahead – without searching around in the app.',items=[('route','Good routes for every outing.','OnPath routes differently for each activity: by bike on cycleways and quiet side roads, by gravel bike happily on gravel, by mountain bike on trails, on foot on paths up to your difficulty. Main roads only when there is no other way.'),('clock','You know when you will arrive.','After about 15 minutes the arrival time follows your own pace, uphill, flat and downhill separately.'),('pin','Is the hut open?','One tap opens the place in Google Maps, with opening hours and photos. Back in OnPath you add it to your route as a stop.'),('vibrate','Your phone stays in your pocket.','Before a junction it vibrates: once for left, twice for right. The lock screen shows the next junction and your arrival time.'),('profile','No nasty surprises.','Before you start you see gradients, surfaces and notes like “120 m pushing · 2 steep sections” or “Ferry – check times”.'),('cable','Cable car or bus? Your tour still adds up.','Rides are recognised and can simply be left out at the end.')],links=[('/cycling/','More about cycling'),('/hiking/','More about hiking')])}
SHOTS={'de':dict(top='So sieht OnPath aus',tag='App-Bildschirme',ctl='Bildschirm wählen',items=[('plan-wandern','Wandern','Planung einer Wanderung von Vellau zur Leiteralm mit Karte, Zeit und Höhenprofil','Wanderung T2 von Vellau zur Leiteralm: Zeit, Höhenmeter und ein Hinweis auf zwei steile Abschnitte – bevor du losgehst.'),('plan-ebike','E-Bike','Dieselbe Strecke mit dem E-Bike geplant, mit Hinweis auf Schiebestrecke','Dieselbe Strecke mit dem E-Bike: Du siehst vorher, wo es unbefestigt ist und wo du 120 m schieben musst.'),('ort-google-maps','Ort finden','Menü zur Leiteralm mit „Zur Route hinzufügen“ und „In Google Maps öffnen“','Leiteralm gefunden: zur Route hinzufügen oder bei Google Maps nach den Öffnungszeiten schauen.')]),'en':dict(top='What OnPath looks like',tag='App screens',ctl='Choose a screen',items=[('plan-wandern','Hiking','A hike planned from Vellau to the Leiteralm with map, time and elevation profile','A T2 hike from Vellau to the Leiteralm: time, climbing and a note about two steep sections – before you set off.'),('plan-ebike','E-bike','The same route planned by e-bike, with a note about pushing','The same route by e-bike: you see in advance where it is unpaved and where you push for 120 m.'),('ort-google-maps','Find a place','Menu for the Leiteralm with “Add to route” and “Open in Google Maps”','Found the Leiteralm: add it to your route or check the opening hours in Google Maps.')])}
def app_shots(lang='de'):
    S=SHOTS[lang]; first=S['items'][0]
    src=lambda k:'/assets/app/'+k+'-'+lang+'.webp'
    buttons=''.join('<button data-shot="'+src(k)+'" data-alt="'+alt+'" data-text="'+txt+'" aria-pressed="'+('true' if i==0 else 'false')+'">'+label+'</button>' for i,(k,label,alt,txt) in enumerate(S['items']))
    return '<div class="demo shots"><div class="demo-top"><span>'+S['top']+'</span><span class="tag">'+S['tag']+'</span></div><div class="shots-phone"><img id="shot-img" src="'+src(first[0])+'" alt="'+first[2]+'" width="600" height="1333" loading="lazy"></div><div class="demo-controls" aria-label="'+S['ctl']+'">'+buttons+'</div><p id="shot-text" aria-live="polite">'+first[3]+'</p></div>'
FEATURES={'de':dict(rows=[('route','Gute Routen für jede Tour.','Radwege fürs Rad, Schotter fürs Gravelbike, Trails fürs MTB, passende Wege zu Fuß.','plan-ebike'),('profile','Keine bösen Überraschungen.','Steigungen, Untergrund und Schiebestellen siehst du vor dem Start.','plan-wandern'),('pin','Hat die Hütte offen?','Öffnungszeiten in Google Maps ansehen, dann als Stopp übernehmen.','ort-google-maps')],also='<b>Außerdem:</b> Vibration vor jeder Abzweigung · Ankunftszeit, die dein Tempo lernt · Seilbahn und Bus werden erkannt.'),
'en':dict(rows=[('route','Good routes for every outing.','Cycleways for bikes, gravel for gravel bikes, trails for MTBs, fitting paths on foot.','plan-ebike'),('profile','No nasty surprises.','You see gradients, surfaces and pushing sections before you start.','plan-wandern'),('pin','Is the hut open?','Check opening hours in Google Maps, then add it as a stop.','ort-google-maps')],also='<b>Also:</b> a vibration before every junction · an arrival time that learns your pace · cable cars and buses recognised.')}
WAYS={'de':dict(eye='Zwei Wege zur Tour',h='Am großen Bildschirm planen –<br>unterwegs einfach losgehen.',lead='Plane, wie es gerade passt: schnell auf dem Handy oder in Ruhe am Computer. Beide berechnen dieselben Routen.',cards=[('phone','Spontan unterwegs',['Auf die Karte tippen – die Route steht.','Einen Ort aus Google Maps teilen und als Ziel übernehmen.','Ein Abstecher? Einen Punkt dazu, fertig.']),('computer','In Ruhe von zu Hause',['Große Karte, Punkte mit der Maus verschieben.','Eine GPX-Datei öffnen und daraus deine Route machen.','Per QR-Code aufs Handy. Oder einmal koppeln: Dann ist jeder Plan von selbst dort.'])],note='Kostenlos, ohne Konto, ohne Installation.',open='Planer öffnen'),
'en':dict(eye='Two ways to plan',h='Plan on the big screen –<br>then just head out.',lead='Plan the way that suits you: quickly on your phone or calmly at the computer. Both calculate the same routes.',cards=[('phone','Spontaneously, on the way',['Tap the map – the route is there.','Share a place from Google Maps and make it your destination.','A detour? Add a point, done.']),('computer','Calmly, at home',['A big map, points moved with the mouse.','Open a GPX file and turn it into your route.','Send it to your phone by QR code. Or pair once: every plan then gets there by itself.'])],note='Free, no account, nothing to install.',open='Open the planner')}
WEBSHOT={'de':dict(tabs=[('web-wandern','Planen','Der Planer im Browser: eine Wanderung von Vellau zur Leiteralm mit Zeit, Höhenprofil und Hinweisen','Große Karte, Höhenprofil und Hinweise wie „2 steile Abschnitte“ – wie in der App.'),('web-qr','Aufs Handy','Der Dialog „Aufs Handy · Teilen“ mit QR-Code','Mit der OnPath-App den Code scannen – schon ist die Tour auf dem Handy.')],ctl='Planer-Bildschirm wählen'),
'en':dict(tabs=[('web-wandern','Plan','The browser planner: a hike from Vellau to the Leiteralm with time, elevation profile and notes','A big map, elevation profile and notes like “2 steep sections” – as in the app.'),('web-qr','To your phone','The “Send to phone · Share” dialog with a QR code','Scan the code with the OnPath app – the tour is on your phone.')],ctl='Choose a planner screen')}
def web_shot(lang='de'):
    W=WEBSHOT[lang]; t0=W['tabs'][0]; src=lambda k:'/assets/app/'+k+'-de.webp'
    btns=''.join('<button data-web="'+src(k)+'" data-alt="'+alt+'" data-text="'+txt+'" aria-pressed="'+('true' if i==0 else 'false')+'">'+lab+'</button>' for i,(k,lab,alt,txt) in enumerate(W['tabs']))
    return '<figure class="web-shot"><div class="browser-bar" aria-hidden="true"><i></i><i></i><i></i><span>plan.onpath.earth</span></div><img id="web-img" src="'+src(t0[0])+'" alt="'+t0[2]+'" width="1440" height="900" loading="lazy"><figcaption><div class="web-tabs" role="group" aria-label="'+W['ctl']+'">'+btns+'</div><span id="web-text" aria-live="polite">'+t0[3]+'</span></figcaption></figure>'
def ways_section(lang='de'):
    W=WAYS[lang]; T=WEBSHOT[lang]['tabs']
    ways=''.join('<div class="way-lite">'+icon(ic)+'<div><h3>'+t+'</h3><ul>'+''.join('<li>'+x+'</li>' for x in li)+'</ul></div></div>' for ic,t,li in W['cards'])
    phone_alt='OnPath auf dem Handy: dieselbe Wanderung, bereit zum Losgehen' if lang=='de' else 'OnPath on the phone: the same hike, ready to go'
    duo='<figure class="duo"><div class="duo-browser"><div class="browser-bar" aria-hidden="true"><i></i><i></i><i></i><span>plan.onpath.earth</span></div><img src="/assets/app/web-wandern-de.webp" alt="'+T[0][2]+'" width="1440" height="900" loading="lazy"></div><img class="duo-phone" src="/assets/app/plan-wandern-'+lang+'.webp" alt="'+phone_alt+'" width="600" height="1333" loading="lazy"></figure>'
    return '<section class="section" id="'+('planen' if lang=='de' else 'plan')+'"><div class="wrap split ways-split"><div><p class="eyebrow">'+W['eye']+'</p><h2>'+W['h']+'</h2><p class="ways-lead">'+W['lead']+'</p>'+ways+'<div class="ways-cta"><a class="button" href="https://plan.onpath.earth/">'+W['open']+icon('arrow')+'</a><span class="ways-note">'+W['note']+'</span></div></div>'+duo+'</div></section>'
EXTRA={'de':[('clock','Du weißt, wann du ankommst.','Nach etwa 15 Minuten richtet sich die Ankunftszeit nach deinem Tempo – bergauf, flach und bergab getrennt.'),('vibrate','Das Handy lenkt nicht ab.','Zu Fuß bleibt es in der Tasche: Vor einer Abzweigung vibriert es, einmal für links, zweimal für rechts. Am Lenker zeigt es nur Pfeil, Entfernung und Ankunft auf schwarzem Grund – die Karte erscheint erst kurz vor der Abbiegung.'),('cable','Mit Seilbahn oder Bus? Die Tour stimmt trotzdem.','Fahrten werden erkannt. Am Ende nimmst du sie mit einem Tipp aus Strecke und Zeit heraus.')],
'en':[('clock','You know when you will arrive.','After about 15 minutes the arrival time follows your pace – uphill, flat and downhill separately.'),('vibrate','Your phone does not distract you.','On foot it stays in your pocket: before a junction it vibrates, once for left, twice for right. On the handlebar it shows only an arrow, distance and arrival on a black screen – the map appears shortly before the turn.'),('cable','Cable car or bus? The tour still adds up.','Rides are recognised. At the end, one tap leaves them out of distance and time.')]}
SMALL={'de':dict(eye='Was OnPath besser kann',h='Kleine Details.<br>Große Ruhe unterwegs.',cols=[('Unterwegs',[('Nichts wird ohne Frage umgeplant.','Kommst du vom Weg ab, vibriert das Handy und fragt. Die alte Route bleibt grau sichtbar.'),('Keine Änderung aus Versehen.','Beim Navigieren reagiert die Karte nicht auf Berührung. Zum Ändern schiebst du einen Schalter.'),('Speichern ohne viele Fragen.','Tour beenden ist ein Tipp. Den Namen schlägt OnPath vor – nach den Orten, durch die du gekommen bist.'),('Keine Tour geht verloren.','Jeder Punkt wird sofort gespeichert. Die Tour endet nur, wenn du sie beendest – auch nach einem Neustart.')]),('Beim Planen',[('Ehrlich, wenn es nicht geht.','Ist ein Ziel mit deiner Aktivität nicht erreichbar, zeigt OnPath die Lücke – statt heimlich einen Umweg zu nehmen.'),('Die Karte zeigt, was für dich geht.','Wege in Grün, Schwarz, Grau oder Rot – je nachdem, ob sie für deine Aktivität passen.'),('Wandern nach SAC-Skala.','T1 bis T5: Schwierigere Wege lässt OnPath aus, Klettersteige immer. Gut, wenn du für andere planst.'),('Adressen auch ohne Netz.','Straße mit Hausnummer, Dorf, Hütte oder Gipfel – gefunden direkt auf dem Handy.')])],link=('/hilfe/','Alles Schritt für Schritt in der Hilfe')),
'en':dict(eye='What OnPath does better',h='Small details.<br>Peace of mind on the way.',cols=[('On the way',[('Nothing is re-routed without asking.','If you leave the route, the phone vibrates and asks. The old route stays visible in grey.'),('No changes by accident.','While navigating, touching the map does nothing. To edit, you slide a switch.'),('Saving without a lot of questions.','Ending a tour is one tap. OnPath suggests the name from the places you passed.'),('No tour gets lost.','Every point is stored at once. A tour ends only when you end it – even after a restart.')]),('When planning',[('Honest when it does not work.','If a destination cannot be reached with your activity, OnPath shows the gap instead of quietly making a detour.'),('The map shows what works for you.','Ways in green, black, grey or red – depending on whether they suit your activity.'),('Hiking by SAC scale.','T1 to T5: harder trails are left out, via ferratas always. Useful when you plan for others.'),('Addresses without signal.','Street and house number, village, hut or peak – found right on the phone.')])],link=('/help/','Everything step by step in the help'))}
OPEN={'de':dict(eye='Das gehört zu OnPath',h='Offen entwickelt.<br>Der Kern bleibt kostenlos.',lead='Eine nützliche App für draußen – auch für alle, die nur ab und zu eine Tour planen.',pts=[('Der Kern ist immer kostenlos.','Planen, navigieren und aufzeichnen kosten nichts. Das bleibt so – auch wenn du OnPath nur gelegentlich nutzt.'),('Deine Touren gehören dir.','Ohne Konto und ohne Werbung. Deine Touren liegen auf deinem Handy und zusätzlich als GPX-Datei in einem Ordner deiner Wahl.'),('Der Bauplan ist öffentlich.','Der App-Code ist „Open Source“. Jeder kann nachsehen, was die App tut. Du benutzt OnPath ganz normal, ohne Programmierkenntnisse.')],link=('/ausblick/','Mehr zum freien Kern und zur Finanzierung')),
'en':dict(eye='Part of the idea',h='Developed in the open.<br>The core stays free.',lead='A useful app for the outdoors – also for everyone who only plans a tour now and then.',pts=[('The core is always free.','Planning, navigating and recording cost nothing. That stays so – even if you only use OnPath occasionally.'),('Your tours are yours.','No account and no ads. Your tours live on your phone and also as GPX files in a folder you choose.'),('The blueprint is public.','The app code is open source. Anyone can check what the app does. You use OnPath normally, without programming skills.')],link=('/whats-next/','The free core and funding'))}
def open_section(lang='de'):
    O=OPEN[lang]
    return '<section class="section"><div class="wrap"><div class="section-heading stacked"><div><p class="eyebrow">'+O['eye']+'</p><h2>'+O['h']+'</h2></div><p>'+O['lead']+'</p></div><div class="points">'+''.join('<p><b>'+t+'</b>'+x+'</p>' for t,x in O['pts'])+'</div><a class="text-link" href="'+O['link'][0]+'">'+O['link'][1]+' →</a></div></section>'
def small_section(lang='de'):
    S=SMALL[lang]
    cols=''.join('<div><h3>'+t+'</h3><ul>'+''.join('<li><b>'+b+'</b> '+x+'</li>' for b,x in items)+'</ul></div>' for t,items in S['cols'])
    return '<section class="section soft"><div class="wrap"><div class="section-heading stacked"><div><p class="eyebrow">'+S['eye']+'</p><h2>'+S['h']+'</h2></div></div><div class="small-cols">'+cols+'</div><a class="text-link" href="'+S['link'][0]+'">'+S['link'][1]+' →</a></div></section>'
EXTRA_SHOT={'de':{'ankunft':('Navigation mit dem Rad: nächste Abzweigung, Restzeit und Ankunft 10:20','Unterwegs immer im Blick: wie weit, wie lange und wann du ankommst.'),'ruheanzeige':('Ruheanzeige am Rad: schwarzer Bildschirm mit Pfeil, 1,0 km Links und Ankunft 10:20','Am Lenker nur Pfeil, Entfernung und Ankunft. Die Karte kommt kurz vor der Abzweigung.'),'fahrt':('Tour beenden: OnPath hat eine Liftfahrt erkannt und fragt, was zählen soll','Mit dem Sessellift nach Vellau: OnPath erkennt die Fahrt und fragt, was zählen soll.')},
'en':{'ankunft':('Navigating by bike: next turn, time left and arrival 10:20 (German screen)','Always in view on the way: how far, how long and when you arrive.'),'ruheanzeige':('Rest view on the bike: black screen with arrow, 1.0 km left and arrival 10:20','On the handlebar only arrow, distance and arrival. The map returns shortly before the turn.'),'fahrt':('Ending a tour: OnPath recognised a chairlift ride and asks what should count','By chairlift to Vellau: OnPath recognises the ride and asks what should count.')}}
def more_section(lang='de'):
    M=MORE[lang]; F=FEATURES[lang]; S={k:(alt,txt) for k,_,alt,txt in SHOTS[lang]['items']}
    src=lambda k:'/assets/app/'+k+'-'+lang+'.webp'
    rows=''.join('<button class="feature-row" data-shot="'+src(k)+'" data-alt="'+S[k][0]+'" data-text="'+S[k][1]+'" aria-pressed="'+('true' if i==0 else 'false')+'">'+icon(ic)+'<span><b>'+t+'</b>'+x+'</span></button>' for i,(ic,t,x,k) in enumerate(F['rows']))
    first=F['rows'][0][3]
    phone='<div class="demo shots"><div class="demo-top"><span>'+SHOTS[lang]['top']+'</span><span class="tag">'+SHOTS[lang]['tag']+'</span></div><div class="shots-phone"><img id="shot-img" src="'+src(first)+'" alt="'+S[first][0]+'" width="600" height="1333" loading="lazy"></div><p id="shot-text" aria-live="polite">'+S[first][1]+'</p></div>'
    links=''.join('<a class="text-link" href="'+u+'">'+l+' →</a>' for u,l in M['links'])
    return '<section class="section soft" id="'+('so-gehts' if lang=='de' else 'how')+'"><div class="wrap split"><div><p class="eyebrow">'+M['eye']+'</p><h2>'+M['h']+'</h2><div class="feature-rows">'+rows+'</div><div class="mini-rows">'+''.join('<button class="mini-row" data-shot="'+src(k)+'" data-alt="'+EXTRA_SHOT[lang][k][0]+'" data-text="'+EXTRA_SHOT[lang][k][1]+'" aria-pressed="false">'+icon(ic)+'<span><b>'+t+'</b>'+x+'</span></button>' for (ic,t,x),k in zip(EXTRA[lang],['ankunft','ruheanzeige','fahrt']))+'</div><div class="more-links">'+links+'</div></div>'+phone+'</div></section>'

body='''<section class="hero"><div class="wrap hero-grid"><div class="hero-copy"><p class="eyebrow"><span class="status-dot"></span> Die App für Rad- und Wandertouren</p><h1>Deine Tour.<br><span>Einfach geplant.</span></h1><p class="lead">Ob mit dem Rad oder zu Fuß: Wähle dein Ziel. OnPath findet den Weg dorthin. Unterwegs kannst du deine Tour ändern – auch ohne Empfang, wenn die Karten vorher geladen sind.</p><div class="actions">'''+button('/ausprobieren/','Die App kennenlernen')+'''<a class="plain-link" href="https://plan.onpath.earth/">Im Browser ausprobieren – ohne Installation →</a></div><p class="hero-note">Für Android · Routen auch offline · Ohne OnPath-Konto · Frühe Testversion</p></div><figure class="hero-photo"><img src="/assets/vellau-path.webp" alt="Ein breiter Schotterweg mit Holzzaun unter gelbem Herbstlaub bei Vellau" width="1400" height="1054" fetchpriority="high"><img class="hero-phone" src="/assets/app/plan-wandern-de.webp" alt="OnPath auf dem Handy: eine geplante Wanderung mit Karte und Höhenprofil" width="600" height="1333"><figcaption><span>Der nächste Weg wartet schon.</span><span class="photo-location">Vellau bei Algund, Südtirol</span></figcaption></figure></div></section>
<section class="section" id="entdecken"><div class="wrap"><div class="section-heading stacked"><div><p class="eyebrow">Für das, was unterwegs zählt</p><h2>Neue Route –<br>auch im Funkloch.</h2></div><p>OnPath berechnet die Route direkt auf deinem Handy. Deshalb kannst du unterwegs umplanen – auch dort, wo kein Netz ist.</p></div><div class="feature-grid">'''
for num,ic,title,txt in [('01','offline','Kein Empfang? Geht trotzdem.','Lade die Karten vor der Tour, am besten zu Hause im WLAN. Entlang deiner Route lädt OnPath sie schon vorab.'),('02','route','Umplanen, ohne neu anzufangen.','Noch zum Café oder lieber früher zurück? Ändere dein Ziel. Die Aufzeichnung läuft weiter, schon besuchte Punkte werden übersprungen.'),('03','shield','Vom Weg abgekommen? Neue Route, auch ohne Netz.','Verlässt du die Route, vibriert das Handy und fragt, ob du eine neue möchtest. OnPath rechnet sie in Sekunden direkt auf dem Handy aus. Ein versehentlicher Tipp auf die Karte ändert nichts.')]:
 body+='<article class="feature"><div class="feature-top">'+icon(ic)+'<span>'+num+'</span></div><h3>'+title+'</h3><p>'+txt+'</p></article>'
body+='''</div><p class="section-footnote">Beim ersten Laden eines Gebiets kann es einige Minuten dauern. <a href="/hilfe/offline/">So bereitest du dich vor →</a></p></div></section>
'''+more_section('de')+ways_section('de')+small_section('de')+'''<section class="story-section"><div class="wrap story-grid"><div><p class="eyebrow">Die Idee hinter OnPath</p><h2>Mehr Zeit für den Weg.<br>Weniger mit der App.</h2></div><div><p class="story-text">„Ich habe Komoot lange und gern genutzt. Unterwegs wollte ich aber einfacher umplanen können – auch ohne Empfang. Daraus ist OnPath entstanden.“</p><div class="story-author"><img src="/assets/christian.webp" alt="" width="400" height="400"><span><b>Christian Neuhaus</b>Wanderer, Radfahrer und IT-Nerd</span></div><p>Christian Neuhaus entwickelt OnPath aus seinen eigenen Wander- und Radtouren heraus – mit Unterstützung von KI. Im Mittelpunkt stehen dein Weg und deine Tour – ohne Profil, Follower oder Ranglisten.</p><a class="text-link" href="/idee/">Warum ich OnPath baue →</a></div></div></section>'''+open_section('de')+'''
<section class="section soft"><div class="wrap"><div class="cta"><p class="eyebrow">Gemeinsam besser machen</p><h2>Kommst du eine Runde mit?</h2><p>OnPath ist noch jung. Gesucht werden Menschen, die draußen unterwegs sind und sagen, was im Alltag klappt – und was noch nicht.</p><div class="actions">'''+button('/ausprobieren/','Testversion kennenlernen')+'''</div><span class="fine">Für Android ab Version 8 · Noch nicht im Google Play Store · Noch keine Sprachansagen und keine iPhone-Version</span><p class="cta-links"><a class="text-link" href="/hilfe/">Alle Hilfethemen ansehen →</a><a class="text-link" href="/ausblick/">Was schon geht und was noch kommt →</a></p></div></div></section>'''
page('/','Deine Tour. Einfach geplant.','OnPath für Android: Wander- und Radtouren planen, unterwegs ändern und offline navigieren. Ohne Konto und Werbung.',body)

HELP=[
('erste-schritte','Deine erste Tour','Installieren, Gebiet laden und eine kleine Runde planen.','Start Installation Android Berechtigung Standort',[
('OnPath installieren','<p>OnPath läuft auf Android ab Version 8. Für den geplanten Test soll die Installation über Google Play erfolgen. Der Einladungslink wird noch vorbereitet. Den aktuellen Stand findest du unter <a href="/ausprobieren/">OnPath ausprobieren</a>. Eine iPhone-Version gibt es derzeit nicht.</p><p>Die Installation erfolgt als APK-Datei außerhalb des Play Stores. Android kann dafür eine Freigabe verlangen und auf die Signierung der Testversion hinweisen. Wenn du mit APK-Dateien nicht vertraut bist, warte besser auf den geplanten Google-Play-Test.</p>'),
('Zu Hause vorbereiten','<ol><li>Öffne OnPath mit Internetverbindung, möglichst im WLAN.</li><li>Erlaube den Standortzugriff, wenn du deine Position sehen und eine Tour aufzeichnen möchtest.</li><li>Suche dein Ziel oder bewege die Karte in dein Tourengebiet. Warte, bis die Karten und die Daten zur Routenberechnung vollständig geladen sind.</li><li>Wähle deine Aktivität. Beim Wandern legst du außerdem die gewünschte Schwierigkeit fest.</li></ol>'),
('Die erste Runde planen','<p>Halte den Finger auf die Karte, um einen Punkt zu setzen. Setze Start, Ziel und bei Bedarf Zwischenstopps. OnPath verbindet die Punkte über passende Wege. Prüfe Länge, Höhenmeter und Hinweise zur Strecke.</p><p>Beginne am besten mit einer kurzen Strecke, die du kennst. So lernst du die Bedienung ohne Zeitdruck kennen.</p>'),
('Navigation starten','<p>Tippe auf „Navigation starten“. Der Plan bleibt geschützt: Ein kurzer Tipp auf die Karte verändert die Route nicht. Möchtest du unterwegs etwas ändern, wechselst du bewusst in die Planung.</p>')]),
('offline','Ohne Netz unterwegs','Karten vorbereiten und auch im Funkloch umplanen.','Karten Internet WLAN Funkloch Download Flugmodus',[
('Was offline funktioniert','<p>In vollständig geladenen Gebieten kannst du Orte suchen, eine Route planen, navigieren und unterwegs neu berechnen. Die Berechnung findet auf deinem Handy statt.</p>'),
('Vor der Tour laden','<ol><li>Plane die Strecke mit Internetverbindung.</li><li>Lass OnPath die Karten entlang deiner Route laden. Berücksichtige auch Gebiete für mögliche Abstecher und den Rückweg.</li><li>Prüfe den Download-Stand in den Einstellungen bei den Offline-Karten.</li><li>Teste die vorbereitete Strecke vor dem Aufbruch kurz im Flugmodus. Die Karte und die geplante Route müssen sichtbar sein; probiere auch eine kleine Änderung.</li></ol>'),
('Wenn ein Gebiet fehlt','<p>Ein neues Gebiet benötigt Internet. Beim ersten Abruf kann die Bereitstellung einige Minuten dauern. Starte die Vorbereitung deshalb zu Hause. Sind nur Teile geladen, ist noch nicht alles offline verfügbar.</p>'),
('Was Internet braucht','<p>Neue Karten, App-Updates und zusätzliche Online-Suchergebnisse benötigen eine Verbindung. Wenn du einen Ort in Google Maps öffnest, gelten außerdem dessen Offline-Möglichkeiten und Datenverbindungen.</p>')]),
('route-planen','Eine eigene Route planen','Punkte setzen, Schwierigkeit wählen und die Strecke prüfen.','Punkte Route Wandern Rad T1 T2 T3 Höhenprofil Planung',[
('Aktivität auswählen','<p>Wähle Fahrrad, Gravelbike, E-Bike, MTB, E-MTB oder Wandern. Beim Wandern kannst du die Schwierigkeit von T1 (einfache Wanderwege) bis T5 (anspruchsvolle alpine Wege) einstellen. OnPath berücksichtigt die in den Kartendaten eingetragene Schwierigkeit.</p>'),
('Punkte setzen und ändern','<p>Halte den Finger auf eine freie Stelle in der Karte, um einen Punkt zu setzen. Halte einen bestehenden Punkt gedrückt, um seine Möglichkeiten zu öffnen. Möchtest du einen Punkt auf der Karte versetzen, löschst du ihn und setzt ihn neu.</p><p>In der aufgeklappten Punkteliste kannst du die Reihenfolge am Griff verändern und Punkte entfernen. Änderungen lassen sich rückgängig machen. Außerdem kannst du die Route umkehren oder zu einer Rundtour ergänzen.</p>'),
('Die Strecke ansehen','<p>Das Höhenprofil zeigt, wo es auf- und abwärts geht. In den Routendetails findest du Wegarten und Untergrund. Hinweise können etwa auf Treppen, Schiebestellen oder eine Fähre aufmerksam machen.</p><p>Kann ein Ziel mit deiner Aktivität nicht erreicht werden, zeigt OnPath den fehlenden Abschnitt. Eine gestrichelte Verbindung ist kein bestätigter begehbarer Weg.</p>'),
('Schwierigkeit ist keine Garantie','<p>Die Planung beruht auf OpenStreetMap. Angaben können fehlen oder veraltet sein. Prüfe bei Bergtouren zusätzlich Wetter, Wegzustand und deine Erfahrung. Sperrungen und Hinweise vor Ort gehen immer vor.</p>')]),
('unterwegs-aendern','Unterwegs die Route ändern','Einen Abstecher einbauen und die Aufzeichnung fortsetzen.','Navigation Abstecher umplanen Slider neu berechnen Vibration',[
('Bewusst zur Planung wechseln','<p>Schiebe den Regler zum Bearbeiten der Route. So kannst du den weiteren Weg ändern, ohne deine laufende Aufzeichnung zu beenden.</p>'),
('Den weiteren Weg anpassen','<p>Entferne einen nicht mehr benötigten Stopp oder ergänze ein neues Ziel. Kontrolliere anschließend die Strecke. Solange die benötigten Daten auf dem Handy liegen, klappt die Neuberechnung auch ohne Internet.</p>'),
('Weitergehen oder weiterfahren','<p>Wechsle zurück zur Navigation. OnPath führt dich von deinem Standort aus weiter und überspringt bereits besuchte Zwischenpunkte. Deine Aufzeichnung läuft weiter.</p>'),
('Du bist von der Route abgewichen','<p>OnPath meldet sich per Vibration und fragt nach, ob du eine neue Route möchtest. Es ändert den Weg nicht stillschweigend. Nach der Neuberechnung bleibt die ursprüngliche Route grau sichtbar.</p>')]),
('orte','Orte suchen & Google Maps nutzen','Ein Café finden, einen Ort teilen oder Öffnungszeiten nachsehen.','Google Suche Adresse Hütte Gipfel teilen Öffnungszeiten Photon',[
('In OnPath suchen','<p>Tippe in die Suche und gib einen Ort oder eine Adresse ein. Die geladenen Karten enthalten unter anderem Straßen, Hausnummern, Hütten, Gipfel und Bahnhöfe. Mit Internet ergänzt OnPath die Liste um Online-Ergebnisse.</p>'),
('Einen Ort aus Google Maps übernehmen','<ol><li>Öffne den gewünschten Ort in Google Maps.</li><li>Tippe auf „Teilen“ und wähle OnPath.</li><li>Prüfe den markierten Ort auf der Karte.</li><li>Übernimm ihn als Start, Zwischenstopp oder Ziel.</li></ol><p>Übernommen werden der Ort und sein Name – keine vollständige Google-Route, Bewertungen oder Fotos. Bei einem verkürzten Link kann eine Internetverbindung zum Auflösen nötig sein.</p>'),
('Öffnungszeiten oder Bilder ansehen','<p>Öffne in OnPath den gewünschten Ort und seine Details. Von dort kannst du zu Google Maps wechseln, um Öffnungszeiten, Bilder oder Bewertungen anzusehen. Kehre danach zu OnPath zurück und ergänze den Ort als Zwischenstopp oder Ziel. Den Weg dorthin berechnet OnPath für deine gewählte Aktivität.</p>'),
('Welche Daten dabei übertragen werden','<p>Für Online-Suchergebnisse wird eine ungefähre Position von etwa einem Kilometer Genauigkeit übermittelt. Bei Google Maps gelten die Bedingungen und Datenschutzhinweise von Google. <a href="/datenschutz/">Mehr zum Datenschutz</a>.</p>')]),
('gpx','Touren als Datei öffnen und sichern','Vorhandene Touren mitnehmen und deine eigenen behalten.','GPX Import Export Verein speichern Sicherung Backup Datei',[
('Was ist eine GPX-Datei?','<p>Eine GPX-Datei enthält den Verlauf einer Strecke. Viele Tourismusregionen, Wanderseiten und Radvereine stellen Touren in diesem Format bereit. So kannst du eine Tour mit verschiedenen Apps nutzen.</p>'),
('Eine Strecke öffnen','<p>Lade die GPX-Datei auf dein Handy. Öffne sie mit OnPath, zum Beispiel über die Dateiverwaltung von Android. Prüfe, ob Strecke und Aktivität passen. Lade vor dem Start die benötigten Karten vollständig.</p>'),
('Was du damit machen kannst','<p>Du kannst importierten GPX-Strecken folgen. Sie lassen sich derzeit noch nicht in einen frei bearbeitbaren OnPath-Plan umwandeln. Wenn du selbst flexibel planen möchtest, lege die Route mit eigenen Punkten an.</p>'),
('Eigene Touren sichern','<p>Wähle einen Ordner für deine GPX-Dateien. OnPath legt dort zusätzlich eine Kopie jeder gespeicherten Route und abgeschlossenen Tour ab. Für eine vollständige Sicherung gibt es außerdem einen ZIP-Export.</p><p>Speichern auf dem Handy ist keine Sicherung gegen Verlust des Handys. Kopiere wichtige Dateien regelmäßig auf ein weiteres Gerät oder an einen von dir gewählten Speicherort.</p>')]),
('probleme','Wenn etwas nicht klappt','Fehlende Karten, Standortprobleme und Rückmeldungen.','Fehler Probleme GPS Diagnose Akku Download Support',[
('Die Karte lädt nicht','<p>Prüfe deine Internetverbindung und den Download-Stand bei den Offline-Karten. Ein erstmals angefordertes Gebiet braucht länger. Im Funkloch kann OnPath ein fehlendes Gebiet nicht nachladen.</p>'),
('Mein Standort fehlt','<p>Prüfe, ob die Standortfunktion von Android eingeschaltet ist und OnPath die nötige Berechtigung hat. Unter freiem Himmel lässt sich ein Standort meist leichter bestimmen als in Gebäuden. Warte auf eine brauchbare Position, bevor du die Navigation beurteilst.</p>'),
('Die Tour wurde unterbrochen','<p>OnPath speichert aufgezeichnete Punkte fortlaufend und ist darauf ausgelegt, eine Tour nach einem Neustart fortzusetzen. Öffne die App und prüfe, ob eine laufende Tour zur Fortsetzung angeboten wird. Die Testversion kann dennoch Fehler enthalten.</p>'),
('Einen Fehler melden','<p>Notiere dein Handy-Modell, die OnPath-Version, die Situation und was du erwartet hast. Unter Einstellungen → Diagnose → Export kannst du zusätzliche Informationen als Datei erzeugen. Prüfe sie vor dem Weitergeben, besonders auf Orts- und Tourdaten.</p><p><a href="'+GITHUB+'/issues">Auf GitHub einen Fehler melden ↗</a>. Ein GitHub-Konto ist dafür nötig. Öffentlich eingestellte Meldungen und Anhänge können andere lesen; verschicke keine privaten Daten unbedacht. OnPath sendet den Export nicht automatisch.</p>')])]


HELP.extend([
('navigation','Unterwegs den Weg finden','Abzweigungen, Ankunftszeit und das Ende deiner Tour.','Navigation Vibration links rechts Zeit Sperrbildschirm Aufzeichnung',[
('Abzweigungen erkennen','<p>OnPath zeigt die nächste Abzweigung. Das Handy vibriert einmal für links und zweimal für rechts. Probiere die Hinweise zuerst auf einer bekannten Strecke aus: Wie deutlich du sie spürst, hängt auch davon ab, wo du das Handy trägst.</p>'),
('Ein Blick auf den Sperrbildschirm','<p>Die OnPath-Benachrichtigung zeigt die nächste Abzweigung und die Ankunftszeit. Du musst dafür nicht jedes Mal die App öffnen. Sprachansagen gibt es noch nicht.</p>'),
('Die Zeit passt sich deinem Tempo an','<p>Zu Beginn nutzt OnPath deine Fitness-Einstellung. Nach ungefähr 15 Minuten und einem Kilometer berücksichtigt die App dein tatsächliches Tempo – getrennt für bergauf, eben und bergab. Die Ankunftszeit bleibt eine Schätzung.</p>'),
('Die Tour beenden und behalten','<p>Beende die Tour bewusst in der App und speichere sie. Ein bloßes Sperren des Bildschirms beendet sie nicht. Die Punkte werden während der Tour fortlaufend gespeichert.</p>')]),
('akku-sicherung','Akku und Sicherung','Damit die Aufzeichnung weiterläuft und deine Touren erhalten bleiben.','Akku Hintergrund Batterie Sicherung Papierkorb ZIP Backup',[
('Wenn die Aufzeichnung im Hintergrund stoppt','<p>Prüfe in den Android-Einstellungen bei Apps → OnPath die Standortfreigabe, Benachrichtigungen und die Akku-Einstellung. Eine starke Akku-Beschränkung kann die App im Hintergrund beenden. Je nach Handyhersteller heißen diese Einstellungen etwas anders.</p><p>Falls nötig, erlaube OnPath die Nutzung ohne Akku-Einschränkung. Prüfe anschließend auf einer kurzen Strecke, ob bei gesperrtem Bildschirm weiter aufgezeichnet wird.</p>'),
('Vor einer längeren Wanderung','<p>Lade das Handy vorher und nimm bei Bedarf eine Powerbank mit. Der Akkuverbrauch ist noch nicht auf vielen Geräten gemessen. Display, Gerät und Empfang beeinflussen die Laufzeit.</p>'),
('Eine zweite Kopie deiner Touren','<p>Richte in OnPath einen Ordner für die zusätzlichen Tourdateien ein. Kopiere wichtige Dateien regelmäßig auf den Computer oder einen anderen Speicher. Eine Kopie auf demselben Handy hilft nicht, wenn das Handy verloren geht.</p>'),
('Alles sichern oder wiederherstellen','<p>In den Sicherungsfunktionen kannst du alle Touren gemeinsam als ZIP-Datei exportieren. Gelöschte Touren bleiben 30 Tage im Papierkorb. Nach einer Neuinstallation kann OnPath die Touren aus dem vorhandenen Sicherungsordner wiederherstellen; der Ordner muss dafür erneut zugänglich sein.</p>')])])

def article(path,eye,title,desc,sections,help_page=False):
 side='<aside class="side-nav"><b>'+('Hilfe & erste Schritte' if help_page else 'Auf dieser Seite')+'</b>'
 if help_page:side+=''.join('<a '+('aria-current="page" ' if path=='/hilfe/'+s+'/' else '')+'href="/hilfe/'+s+'/">'+t+'</a>' for s,t,_,_,_ in HELP)
 else:side+=''.join('<a href="#abschnitt-'+str(i)+'">'+t+'</a>' for i,(t,_) in enumerate(sections))
 side+='</aside>'
 prose=''.join('<section id="abschnitt-'+str(i)+'"><h2>'+t+'</h2>'+v+'</section>' for i,(t,v) in enumerate(sections))
 content=ph(eye,title,desc,('<a href="/hilfe/">Hilfe</a> <span>/</span> ' if help_page else '')+title)+'<section class="section"><div class="wrap article-layout">'+side+'<article class="prose">'+prose+'<div class="article-end"><a href="/hilfe/">← Alle Hilfethemen</a><a href="/ausprobieren/">OnPath ausprobieren →</a></div></article></div></section>'
 page(path,title,desc,content,'/hilfe/' if help_page else path)
for slug,title,desc,keys,sections in HELP:article('/hilfe/'+slug+'/','Hilfe & erste Schritte',title,desc,sections,True)
helpbody=ph('OnPath verstehen','Wie können wir dir helfen?','Kurze Anleitungen für deine erste Tour – und für die kleinen Fragen unterwegs.','Hilfe')+'<section class="section help-section"><div class="wrap"><div class="help-search"><label for="help-search">Hilfethema suchen</label><div>'+icon('search')+'<input type="search" id="help-search" placeholder="Zum Beispiel: Karten, GPX oder Google Maps" autocomplete="off"></div></div><p id="search-count" class="fine" role="status">9 Hilfethemen</p><div class="help-grid">'
for slug,title,desc,keys,_ in HELP:helpbody+='<a class="help-card" data-keywords="'+keys+'" href="/hilfe/'+slug+'/"><h2>'+title+'</h2><p>'+desc+'</p><span aria-hidden="true">→</span></a>'
helpbody+='</div><p id="no-results" hidden>Kein passendes Thema gefunden. Versuche es mit „Karten“, „Route“ oder „GPX“.</p></div></section>'
page('/hilfe/','Hilfe & erste Schritte','Einfach erklärte Hilfe zu OnPath: offline planen, Touren ändern, Orte suchen und GPX-Dateien nutzen.',helpbody,'/hilfe/')

article('/wandern/','Zu Fuß unterwegs','Zeit für deinen Weg.','Du musst nicht jeden Weg kennen, um eine eigene Wanderung zu planen. OnPath hilft dir, aus einem Ziel eine Strecke zu machen.',[
('Du wählst das Ziel. OnPath verbindet die Wege.','<p>Suche zuerst dein Ziel, etwa eine Hütte oder einen Ort. Ergänze bei Bedarf einen Zwischenstopp. OnPath verbindet die Punkte über Wege. Du siehst die Entfernung, die Steigungen und die ungefähre Dauer. Wähle die Schwierigkeit passend zu deiner Erfahrung. OnPath verwendet bei der Planung keine als schwieriger eingestuften Wege als eingestellt und keine Klettersteige.</p>'+notice('Mit Augenmaß planen','Die Einstufung hängt von den Kartendaten ab. Wetter, Wegzustand und deine Erfahrung bleiben entscheidend.')),
('Noch zur Hütte – oder früher zurück','<p>Ein guter Wandertag braucht keinen starren Plan. Baue einen Abstecher ein oder ändere das Ziel. Deine Aufzeichnung läuft weiter, während du den restlichen Weg anpasst. Mit vorbereiteten Karten geht das auch ohne Empfang.</p>'),
('Eine Zeitangabe, die sich anpasst','<p>Die erste Schätzung orientiert sich an deiner eingestellten Fitness. Nach etwa 15 Minuten und einem Kilometer berücksichtigt OnPath dein tatsächliches Tempo auf dieser Tour – getrennt nach bergauf, eben und bergab. Pausen werden dabei herausgerechnet.</p>'),
('Weniger aufs Display schauen','<p>Vor einer Abzweigung vibriert das Handy: einmal für links, zweimal für rechts. Auf dem Sperrbildschirm findest du die nächste Abzweigung und die Ankunftszeit. Sprachansagen gibt es noch nicht.</p>'+button('/hilfe/erste-schritte/','Die erste Tour vorbereiten'))])
article('/radfahren/','Mit dem Rad unterwegs','Eine Runde, wie du sie magst.','Am Fluss entlang, durch die Stadt oder über Schotter: Wähle dein Rad und plane deinen Weg.',[
('Das passende Rad auswählen','<p>Fahrrad, Gravelbike, E-Bike, MTB und E-MTB stehen zur Auswahl. Die gewählte Aktivität beeinflusst, welche Wege OnPath bei der Planung bevorzugt. In den Routendetails siehst du Untergrund und Wegarten.</p>'),
('Vorher wissen, was auf der Strecke liegt','<p>Hinweise können dich auf Treppen, steile Abschnitte, Schiebestellen oder eine Fähre aufmerksam machen. Prüfe bei Fähren vorher die Betriebszeiten. Kartendaten beschreiben die Strecke, können aber keine tagesaktuellen Sperrungen garantieren.</p>'),
('Touren von Verein oder Tourenportal','<p>Du hast von deinem Radverein oder aus einem Tourenportal eine GPX-Datei bekommen? Öffne sie in OnPath und nimm die Strecke mit aufs Rad. Ein OnPath-Konto ist dafür nicht erforderlich.</p><p>Wer eine eigene Tour vorbereitet, kann die Strecke als GPX mitnehmen und weitergeben. Das ist auch bei einer gemeinsamen Ausfahrt praktisch. OnPath selbst ist auf Planung und Navigation ausgerichtet; eine Gruppenverwaltung gibt es nicht.</p>'),
('Unterwegs einen Abstecher einbauen','<p>Für eigene Pläne kannst du den weiteren Weg ändern, ohne die Aufzeichnung zu stoppen. Halte dafür an, passe deine Route an und fahre weiter. Importierte GPX-Strecken lassen sich derzeit noch nicht wie ein eigener Plan bearbeiten.</p>'+button('/hilfe/gpx/','GPX-Touren nutzen'))])
article('/idee/','Persönlich entwickelt','Warum ich OnPath baue.','Ich möchte draußen unterwegs sein. Und eine App, die mir das Planen und Ändern einer Tour leicht macht.',[
('Wer ich bin','<img src="/assets/christian.webp" alt="Christian Neuhaus beim Wandern in den Bergen" class="me" width="400" height="400"><p>Ich bin Christian Neuhaus und ein bisschen ein Nerd: Seit über 30 Jahren lebe und arbeite ich mit IT – dort, wo Technik, Geschäft und Menschen zusammenkommen. Ich probiere gern neue Technik aus, baue kleine Geräte mit Sensoren und Kameras und zeige Kindern, wie Programmieren funktioniert.</p><p>Am liebsten bin ich aber draußen: zu Fuß in den Bergen oder mit dem Rad. Bei OnPath kommt beides zusammen.</p><p class="me-link">Mehr über mich und meine Bastelprojekte: <a href="https://44-2.de/de/">44-2.de</a></p>'),
('Aus eigenen Touren entstanden','<p>Komoot habe ich seit den frühen Jahren viel genutzt. Ich halte es weiterhin für eine gute App.</p><p>Auf meinen Touren haben mich aber bestimmte Dinge immer wieder beschäftigt: eine Route auf dem Handy ändern, unterwegs neu planen, wenn kein Netz da ist, und nach einer Pause einfach weitergehen. Einmal veränderte sich mein Plan sogar, während das Handy in der Tasche war.</p><p>OnPath ist mein Versuch, diese Alltagssituationen einfacher zu lösen.</p>'),
('Die Tour steht im Mittelpunkt','<p>Ich konzentriere mich auf das Wandern und Radfahren: eine passende Strecke planen, sich unterwegs orientieren und den Weg ändern können. Für all das soll kein Profil nötig sein. OnPath hat keinen sozialen Feed und keine Ranglisten.</p><p>Du kannst mit anderen losziehen und Touren als Dateien austauschen. OnPath kümmert sich um den Weg; eine Gruppenverwaltung gehört nicht dazu.</p>'),
('Robust heißt: Überraschungen vermeiden','<p>Eine Route wird nur nach Rückfrage neu berechnet. Zum Bearbeiten wechselst du bewusst in die Planung. Aufgezeichnete Punkte werden laufend gespeichert. Diese Entscheidungen sollen verhindern, dass ein versehentlicher Tipp oder ein unterbrochener Empfang den Tag durcheinanderbringt.</p><p>Das ist der Anspruch. OnPath ist noch jung und bisher hauptsächlich von mir selbst getestet. Ob es auch auf deinem Handy und deinen Wegen gut funktioniert, müssen weitere Praxistests zeigen.</p>'),
('Mit KI entwickelt. Aus eigener Erfahrung gestaltet.','<p>Ich glaube: Mit KI kann man wirklich etwas Besseres bauen – etwas, das alle weiterbringt. Es kommt darauf an, was man daraus macht. OnPath soll genau das zeigen.</p><p>Ich entwickle OnPath mit Unterstützung von KI. Sie hilft mir beim Programmieren und Prüfen. Dadurch kann ich als Einzelperson Ideen schneller umsetzen, als es mir ohne diese Unterstützung möglich wäre.</p><p>Meine Erfahrungen auf dem Rad und beim Wandern geben die Richtung vor: Was muss unterwegs einfach funktionieren? Wo darf die App nicht im Weg sein? Ob eine Lösung taugt, zeigt sich beim Ausprobieren auf echten Touren.</p><p>Ich respektiere, was das Komoot-Team über viele Jahre aufgebaut hat. Mit KI stehen mir heute zusätzliche Möglichkeiten zur Verfügung. Diesen Vorteil möchte ich weitergeben: mit öffentlich zugänglichem Code, freien Kernfunktionen und einer fairen Finanzierung.</p>'),
('Freier Kern und faire Finanzierung','<p>Die Kernfunktionen bleiben kostenlos nutzbar. Spätere Zusatzangebote sollen die laufenden Kosten decken, meine Arbeit vergüten und einen Spendenanteil ermöglichen. Ich möchte ein nützliches Projekt erhalten und weiterentwickeln, kein gewinnorientiertes Geschäftsmodell aufbauen.</p><p>Wie sich Einnahmen und Ausgaben verteilen, soll offen sichtbar sein. <a href="/ausblick/">Mehr zur geplanten Finanzierung</a>.</p>'),
('Was bedeutet „Open Source“ für dich?','<p>OnPath ist „Open Source“. Das heißt: Der Bauplan der App ist öffentlich. Fachkundige können nachsehen, wie sie arbeitet, und Verbesserungen beitragen. Du musst dafür nichts von Programmierung verstehen. Du benutzt die App ganz normal. Die öffentliche Entwicklung allein garantiert keine Fehlerfreiheit. Die Karten stammen aus dem Gemeinschaftsprojekt OpenStreetMap.</p>'+button(GITHUB,'Das Projekt auf GitHub ansehen'))])
article('/ausblick/','Heute & als Nächstes','OnPath wächst mit deinen Touren.','Was du heute ausprobieren kannst – und was für später gedacht ist.',[
('Heute: die Android-App','<p><span class="tag">Als Testversion verfügbar</span></p><p>Eigene Wege planen, sich führen lassen, unterwegs umplanen und Touren speichern. Geladene Gebiete funktionieren auch ohne Netz. Orte aus Google Maps und vorhandene Tourdateien lassen sich übernehmen. Die Oberfläche ist Deutsch oder Englisch.</p><p>Die Testversion ist kostenlos. Sie ist noch nicht im Google Play Store und wird laufend weiterentwickelt.</p>'),
('Neu: am Computer planen','<p><span class="tag">Im Browser verfügbar</span></p><p>Auf <a href="https://plan.onpath.earth/">plan.onpath.earth</a> planst du deine Tour auf einer großen Karte – kostenlos, ohne Konto und ohne Installation. Die Routen sind dieselben wie in der App. Danach hältst du die Handykamera auf den QR-Code, und der Plan ist auf dem Handy.</p>'),
('Im Test: Browser und Handy verbinden','<p><span class="tag">Im Test</span></p><p>Einmal mit der Handykamera den Code auf dem Computerbildschirm erfassen: Danach kommen gespeicherte Pläne von selbst auf beide Geräte – verschlüsselt und ohne OnPath-Konto. Die Verbindung lässt sich jederzeit wieder trennen.</p>'),
('Der Kern bleibt frei','<p>Die wichtigsten Funktionen bleiben kostenlos nutzbar: Routen auf dem Handy planen, navigieren und mit geladenen Karten offline umplanen. OnPath ist Open Source. Der App-Code ist öffentlich, und deine Touren kannst du als Dateien sichern und in anderen Apps nutzen.</p>'),
('Spätere Beiträge: Kosten, Arbeit und Spende','<p>Karten bereitzustellen und die App weiterzuentwickeln kostet Geld und Zeit. Spätere kostenpflichtige Zusatzangebote sollen das Projekt tragen, etwa rund um das Speichern und Abgleichen von Plänen im Browser.</p><ul><li>Ein Teil soll die laufenden Kosten decken, zum Beispiel für Kartenbereitstellung und Betrieb.</li><li>Ein Teil soll meine Entwicklungsarbeit vergüten.</li><li>Ein Teil soll an eine Hilfsorganisation gespendet werden.</li></ul><p>OnPath ist nicht als gewinnorientiertes Geschäftsmodell gedacht. Es soll sich fair tragen und zugleich etwas weitergeben.</p>'),
('Die Aufteilung soll nachvollziehbar sein','<p>Vorgesehen ist eine offene Übersicht: Einnahmen, Gebühren, Betriebskosten, mein Anteil und die tatsächlich geleisteten Spenden. So soll sichtbar werden, wohin das Geld geht.</p><p>Preise, Anteile, Hilfsorganisation, genauer Leistungsumfang und Zahlungsweg stehen noch nicht fest. Es gibt hier noch kein bestellbares Bezahlangebot.</p>')])
# Tester links: fill in when the owner has created the Google Group and the Play test (todo A-012).
TESTER_GROUP_URL=''
PLAY_OPTIN_URL=''
TESTER={'de':dict(
 eye='Frühe Testversion',title='So wirst du Tester.',lead='Vier Schritte, etwa fünf Minuten. Mach am besten alles direkt auf deinem Android-Handy.',
 before_h='Bevor du startest',before=['Ein Android-Handy ab Version 8.','Dein Google-Konto – das, mit dem du im Play Store Apps lädst.','Ein paar Minuten Zeit. Die Freischaltung dauert dann meist ein bis zwei Tage.'],
 check='<b>So findest du dein Google-Konto:</b> Öffne auf dem Handy den Play Store und tippe oben rechts auf das runde Bild. Dort steht deine E-Mail-Adresse. Genau dieses Konto brauchst du gleich.',
 steps=[
  ('Anfrage an die Tester-Gruppe','Tippe unten auf <b>„Zur Tester-Gruppe“</b>. Es öffnet sich eine Seite von Google mit der Gruppe „OnPath Tester“. Tippe dort auf <b>„Beitritt zur Gruppe anfragen“</b>.','Schreib ein paar Worte dazu: wie du unterwegs bist (Wandern, Rad, MTB …), welches Handy du hast und woher du OnPath kennst. Hast du einen Einladungscode, schreib ihn mit hinein. Dann abschicken.','group','Zur Tester-Gruppe','Siehst du keinen Knopf zum Anfragen? Dann bist du bei Google nicht angemeldet. Tippe oben rechts auf „Anmelden“ und nimm das Konto aus dem Play Store.'),
  ('Kurz warten','Christian schaut sich jede Anfrage selbst an. Das dauert meist ein bis zwei Tage.','Danach bekommst du eine E-Mail von Google: Du bist jetzt Mitglied der Gruppe. In dieser E-Mail steht auch der Link für Schritt 3.','','',''),
  ('Bei Google Play Tester werden','Öffne den Link <b>„Bei Google Play Tester werden“</b> – aus der E-Mail oder hier unten. Tippe auf <b>„Tester werden“</b>.','Google bestätigt: Du bist jetzt Tester. Darunter steht ein Link zum Play Store.','play','Bei Google Play Tester werden','Steht dort, dass die App nicht verfügbar ist? Dann ist meist ein anderes Google-Konto angemeldet – siehe „Wenn es hakt“.'),
  ('OnPath installieren','Im Play Store siehst du OnPath. Tippe auf <b>„Installieren“</b>. Fertig.','Neue Versionen kommen wie bei jeder App von selbst über Google Play.','','','')],
 soon='Link folgt in Kürze',
 after='Geschafft? Dann geht es hier weiter: <a href="/hilfe/erste-schritte/">Erste Schritte mit OnPath →</a>',
 faq_h='Wenn es hakt',faq=[
  ('Ich habe kein Google-Konto.','Ohne Google-Konto geht es bei Google Play leider nicht. Fast jedes Android-Handy hat aber schon eins: Es ist das Konto, mit dem du im Play Store Apps lädst.'),
  ('Ich habe mehrere Google-Konten.','Nimm überall dasselbe Konto. Im Play Store wechselst du es so: oben rechts auf das runde Bild tippen, dann auf den kleinen Pfeil neben deinem Namen und das richtige Konto wählen.'),
  ('Google Play sagt: „App nicht gefunden“ oder „nicht verfügbar“.','Meist ist ein anderes Google-Konto angemeldet als in der Gruppe. Prüfe das Konto im Play Store. Ist es richtig, warte ein paar Stunden – Google braucht manchmal etwas, bis die Freischaltung überall ankommt.'),
  ('Ich habe angefragt, aber nichts gehört.','Schau auch im Spam-Ordner nach einer E-Mail von Google Groups. Nach drei Tagen ohne Antwort schreib uns gern – die Adresse steht im <a href="/impressum/">Impressum</a>.'),
  ('Wer sieht meine E-Mail-Adresse?','Nur Christian als Verwalter der Gruppe. Andere Tester sehen sie nicht. Die Adresse bleibt bei Google; OnPath speichert sie nicht.'),
  ('Bekomme ich jetzt viele E-Mails?','Nein. Nur ab und zu eine Nachricht zum Test, zum Beispiel zu einer neuen Version. Du kannst die Gruppe jederzeit verlassen.'),
  ('Kostet das etwas?','Nein. Der Test ist kostenlos.'),
  ('Gibt es OnPath auch fürs iPhone?','Noch nicht. Im Moment gibt es OnPath nur für Android.')],
 more_h='Gut zu wissen',more=[
  ('Eine frühe Testversion','OnPath ist noch jung und wurde bisher vor allem vom Entwickler auf eigenen Touren in Südtirol genutzt. Es fehlen noch eine iPhone-Version und Sprachansagen. Plane für den Anfang eine kurze, bekannte Strecke.'),
  ('Was beim Testen hilft','Du musst dich nicht mit Technik auskennen. Sag einfach, was du machen wolltest, was passiert ist und was du erwartet hast. Auch „Diesen Schritt habe ich nicht verstanden“ hilft weiter.'),
  ('Für technisch Erfahrene','Frühe Fassungen gibt es auch auf <a href="'+GITHUB+'/releases">GitHub</a>. Sie können anders signiert sein als die Play-Fassung. Sichere deine Touren, bevor du zwischen beiden wechselst.')]),
'en':dict(
 eye='Early test version',title='How to become a tester.',lead='Four steps, about five minutes. It is easiest to do everything directly on your Android phone.',
 before_h='Before you start',before=['An Android phone, version 8 or newer.','Your Google account – the one you use to get apps from the Play Store.','A few minutes. Approval then usually takes one or two days.'],
 check='<b>How to find your Google account:</b> open the Play Store on your phone and tap the round picture at the top right. Your email address is shown there. That is the account you need.',
 steps=[
  ('Ask to join the tester group','Tap <b>“Go to the tester group”</b> below. A Google page opens with the group “OnPath Tester”. Tap <b>“Ask to join group”</b>.','Add a few words: how you get around (hiking, cycling, MTB …), which phone you have and how you heard about OnPath. If you have an invitation code, add it. Then send.','group','Go to the tester group','No button to ask? Then you are not signed in to Google. Tap “Sign in” at the top right and use the account from the Play Store.'),
  ('Wait a little','Christian looks at every request himself. This usually takes one or two days.','You then get an email from Google: you are now a member of the group. It also contains the link for step 3.','','',''),
  ('Become a tester on Google Play','Open the link <b>“Become a tester on Google Play”</b> – from the email or below. Tap <b>“Become a tester”</b>.','Google confirms that you are now a tester. Below it there is a link to the Play Store.','play','Become a tester on Google Play','Does it say the app is not available? Usually a different Google account is signed in – see “If something goes wrong”.'),
  ('Install OnPath','The Play Store shows OnPath. Tap <b>“Install”</b>. Done.','New versions arrive by themselves through Google Play, like for any app.','','','')],
 soon='Link coming soon',
 after='Done? Continue here: <a href="/help/getting-started/">First steps with OnPath →</a>',
 faq_h='If something goes wrong',faq=[
  ('I do not have a Google account.','Google Play does not work without one. But almost every Android phone already has one: it is the account you use in the Play Store.'),
  ('I have several Google accounts.','Use the same account everywhere. To switch it in the Play Store: tap the round picture at the top right, then the small arrow next to your name, and choose the right account.'),
  ('Google Play says “item not found” or “not available”.','Usually a different Google account is signed in than the one in the group. Check the account in the Play Store. If it is right, wait a few hours – Google sometimes needs a while.'),
  ('I asked but heard nothing.','Check your spam folder for an email from Google Groups. After three days without an answer, please write to us – the address is in the <a href="/legal/">legal notice</a>.'),
  ('Who sees my email address?','Only Christian as the group manager. Other testers do not see it. The address stays with Google; OnPath does not store it.'),
  ('Will I get lots of emails?','No. Only an occasional message about the test, for example about a new version. You can leave the group at any time.'),
  ('Does it cost anything?','No. The test is free.'),
  ('Is there an iPhone version?','Not yet. OnPath is currently only available for Android.')],
 more_h='Good to know',more=[
  ('An early test version','OnPath is still young and has mainly been used by its developer on his own tours in South Tyrol. There is no iPhone version or spoken directions yet. Start with a short route you know.'),
  ('What helps when testing','You do not need technical knowledge. Just say what you wanted to do, what happened and what you expected. “I did not understand this step” helps too.'),
  ('For technically experienced users','Early builds are also on <a href="'+GITHUB+'/releases">GitHub</a>. They may be signed differently from the Play build. Back up your tours before switching between them.')])}
def tester_page(lang='de'):
    T=TESTER[lang]; links={'group':TESTER_GROUP_URL,'play':PLAY_OPTIN_URL}
    def act(key,label):
        if not key:return ''
        u=links[key]
        return '<a class="button" href="'+u+'" rel="noopener">'+label+icon('arrow')+'</a>' if u else '<span class="button disabled" aria-disabled="true">'+label+' · '+T['soon']+'</span>'
    before='<div class="tester-before"><h2>'+T['before_h']+'</h2><ul>'+''.join('<li>'+icon('check')+'<span>'+x+'</span></li>' for x in T['before'])+'</ul><p class="tester-check">'+T['check']+'</p></div>'
    steps='<ol class="tester-steps">'+''.join('<li><span class="step-no" aria-hidden="true">'+str(i+1)+'</span><div><h3>'+t+'</h3><p>'+a+'</p><p class="step-then">'+b+'</p>'+act(k,l)+('<p class="step-tip"><b>Tipp:</b> ' if lang=='de' else '<p class="step-tip"><b>Tip:</b> ')*bool(tip)+tip+('</p>' if tip else '')+'</div></li>' for i,(t,a,b,k,l,tip) in enumerate(T['steps']))+'</ol>'
    faq='<div class="tester-faq"><h2>'+T['faq_h']+'</h2>'+''.join('<details><summary>'+q+'</summary><p>'+a+'</p></details>' for q,a in T['faq'])+'</div>'
    more='<div class="points">'+''.join('<p><b>'+t+'</b>'+x+'</p>' for t,x in T['more'])+'</div>'
    hero='<section class="page-hero"><div class="wrap"><p class="eyebrow">'+T['eye']+'</p><h1>'+T['title']+'</h1><p class="lead">'+T['lead']+'</p></div></section>'
    return hero+'<section class="section"><div class="wrap tester">'+before+steps+'<p class="tester-after">'+T['after']+'</p>'+faq+'</div></section><section class="section soft"><div class="wrap"><h2>'+T['more_h']+'</h2>'+more+'</div></section>'
page('/ausprobieren/','So wirst du Tester','Vier Schritte, etwa fünf Minuten: über die Tester-Gruppe zu OnPath bei Google Play.',tester_page('de'))
article('/projekt/','Projektinformationen','Offen entwickelt. Klar beschrieben.','OnPath ist ein unabhängiges Projekt von Christian Neuhaus.',[
('Stand dieser Vorschau','<p>Inhaltlicher Stand: 27. Oktober 2026. Abgeglichen mit dem öffentlichen OnPath-Projekt, den Versionshinweisen bis 0.11.5 und den aktuellen Projektunterlagen. Diese neue deutsche Webseite ist als private Vorschau gedacht.</p><p>Anbieterangaben und Datenschutzhinweise sind ergänzt. Vor dem öffentlichen Start werden die tatsächlichen Hosting-Einstellungen geprüft. Bestätigte Testeinladungen und echte App-Screenshots folgen.</p>'),
('Bildnachweis','<p>Foto auf der Startseite: Christian Neuhaus, bei Vellau (Südtirol). Porträt: Christian Neuhaus, privat. Keine KI-generierten Fotos.</p><p>Die vereinfachte Tourengrafik erklärt den Ablauf und ist kein App-Screenshot. Echte Bildschirmaufnahmen werden separat vorbereitet.</p>'),
('Quellcode und Karten','<p><a href="'+GITHUB+'">OnPath auf GitHub</a> · Apache 2.0. Kartendaten: <a href="https://www.openstreetmap.org/copyright">© OpenStreetMap-Mitwirkende</a>. Routenberechnung: <a href="https://github.com/abrensch/brouter">BRouter</a>.</p>'),
('Unabhängigkeit','<p>OnPath ist nicht mit Komoot oder Google verbunden. Genannte Namen gehören den jeweiligen Rechteinhabern.</p>')])
page('/404/','Seite nicht gefunden','Hier geht es zurück zur Übersicht.',ph('Seite nicht gefunden','Hier geht der Weg nicht weiter.','Die gesuchte Seite gibt es hier nicht.')+'<section class="section"><div class="wrap actions">'+button('/','Zur Startseite')+button('/hilfe/','Zur Hilfe',True)+'</div></section>')


from legal_content import DE_LEGAL, DE_PRIVACY
article('/impressum/','Anbieterangaben','Impressum','Anbieter und Kontakt für OnPath.',DE_LEGAL)
article('/datenschutz/','Deine Daten','Datenschutzhinweise','Website und Android-App: verständlich getrennt erklärt.',DE_PRIVACY)
